<script setup lang="ts">
import { directions, formats, scales, type SavedRequest } from '~/utils/scenario-constructor'
defineProps<{ request: SavedRequest }>()
function label(map: Record<string, string>, key: string) { return Object.hasOwn(map, key) ? map[key] : 'Не указано' }
</script>
<template><div class="constructor-review"><h2>Условия мероприятия</h2><dl><dt>Повод</dt><dd>{{ request.custom_event_title || (request.calendar_event_id ? 'Событие календаря' : 'Ежегодная версия традиции') }}</dd><dt>Масштаб и формат</dt><dd>{{ label(scales, request.scale) }} · {{ label(formats, request.format_type) }}</dd><dt>Участники</dt><dd>{{ request.target_grades.join(', ') }} классы · {{ request.participants_count }} человек</dd><dt>Продолжительность</dt><dd>{{ request.duration_minutes }} минут</dd><dt>Направление</dt><dd>{{ label(directions, request.value_direction) }}</dd><dt>Участие семьи</dt><dd>{{ request.family_involvement ? 'Да' : 'Нет' }}</dd><dt>Ресурсы</dt><dd>{{ request.available_resources?.join(', ') || 'Не указаны' }}</dd><dt>Ограничения</dt><dd>{{ request.pedagogical_constraints || 'Не указаны' }}</dd><dt>Создано</dt><dd>{{ request.created_at }}</dd></dl><p class="muted">Сохранённый контекст не заменяет проверку источников и культурных фактов.</p></div></template>
